FICHES.append(fiche(
 id='lfi-nationaliser-banques', affirmation="LFI veut nationaliser les banques, c'est du communisme.", volet='politique', sous_theme='France insoumise',
 mots_cles=['lfi banques', 'melenchon banques', 'nationaliser les banques', 'nationalisation des banques', 'pole public bancaire', 'lfi communisme', 'socialiser les banques', 'insoumis nationalisation', 'banque publique'],
 verdict='trompeur', fiabilite='etabli',
 resume="Trompeur. Le programme de LFI ne propose pas de nationaliser toutes les banques : il veut créer un pôle public bancaire, « socialiser certaines banques de détail » et séparer les banques d'affaires des banques de détail. Quant au « communisme », la France a déjà nationalisé ses grandes banques en 1945, sous le gouvernement du général de Gaulle, puis en 1982. Et l'État possède déjà des banques aujourd'hui : Bpifrance et, via la Caisse des dépôts, La Banque Postale.",
 contexte="La proposition de LFI sur les banques est souvent résumée par « nationaliser les banques » et présentée comme une mesure révolutionnaire, digne d'un régime communiste.",
 explication="Il faut lire le texte réel du programme, puis regarder l'histoire des nationalisations en France et l'existence actuelle de banques publiques.",
 sources=[A_BANQ_LFI_2026, A_BANQ_INSEE_1996, A_BANQ_BNPP_HIST, A_BANQ_BDF_HIST, A_BANQ_SENAT_1981, A_BANQ_BDF_BPI, A_BANQ_CDC_2020],
 faits=[
  fait("Le programme de LFI propose de créer un « pôle public bancaire et de l'assurance » et de « socialiser certaines banques de détail » pour les y intégrer ; il ne parle pas de toutes les banques.", 'a_banq_lfi_2026', '2026', 'Programme L’Avenir en commun', "La mesure vise certaines banques, pas l'ensemble du secteur bancaire.", 'etabli'),
  fait("Fait défavorable : le programme de LFI propose aussi le contrôle des mouvements de capitaux et une séparation stricte des banques d'affaires et de détail, une rupture nette avec le système actuel.", 'a_banq_lfi_2026', '2026', 'Programme L’Avenir en commun', "C'est un projet de transformation profonde de la finance, qu'on peut discuter ; mais ce n'est pas la suppression de la propriété privée.", 'etabli'),
  fait("En décembre 1945, la Banque de France et quatre grandes banques de dépôt sont nationalisées, puis 34 sociétés d'assurances en avril 1946.", 'a_banq_insee_1996', '1945-1946', 'France', "La nationalisation du crédit fait partie de la reconstruction d'après-guerre.", 'etabli'),
  fait("Le général de Gaulle justifiait en 1945 la nationalisation des banques par le besoin d'orienter l'épargne nationale vers la reconstruction du pays.", 'a_banq_bnpp_hist', '1945', 'France', "Le chef de la France libre n'était pas communiste.", 'etabli'),
  fait("La loi du 11 février 1982 nationalise 39 banques et deux compagnies financières, Paribas et Suez ; selon le rapport du Sénat sur le projet, l'État maîtrise alors environ 90 % des dépôts.", 'a_banq_senat_1981', '1981-1982', 'France', "Une nationalisation bancaire de grande ampleur a déjà eu lieu en France, dans une démocratie.", 'etabli', '39'),
  fait("Ces banques ont ensuite été privatisées : Société générale et Paribas en 1987, BNP en 1993.", 'a_banq_insee_1996', '1987-1993', 'France', "Les nationalisations sont réversibles par la voie démocratique : on n'a pas changé de régime.", 'etabli'),
  fait("Aujourd'hui, Bpifrance est détenue à 50 % par l'État et à 50 % par la Caisse des dépôts, qui possède aussi 66 % de La Poste, maison mère de La Banque Postale.", 'a_banq_bdf_bpi', '2020-2021', 'France', "L'État possède déjà des banques ; le débat porte sur leur nombre et leur rôle, pas sur un tabou.", 'etabli', '50 %'),
 ],
 court="LFI ne veut pas nationaliser toutes les banques : son programme parle de « socialiser certaines banques de détail » dans un pôle public. La France a déjà nationalisé ses grandes banques en 1945, sous de Gaulle, et en 1982. Et l'État possède déjà Bpifrance et La Banque Postale.",
 moyen="Le programme de LFI propose de créer un pôle public bancaire, d'y intégrer « certaines banques de détail » et de séparer les banques d'affaires des banques de détail. Il ne parle pas de nationaliser toutes les banques. On peut être en désaccord, mais il faut critiquer ce qui est réellement proposé.\n\nQuant au « communisme » : en 1945, le gouvernement du général de Gaulle a nationalisé la Banque de France et les quatre plus grandes banques de dépôt. En 1982, 39 banques ont été nationalisées. Ces banques ont ensuite été privatisées par des majorités élues. Et aujourd'hui, l'État contrôle déjà Bpifrance et, via la Caisse des dépôts, La Banque Postale. Des banques publiques existent dans une démocratie de marché.",
 detaille="Le texte du programme L'Avenir en commun est précis : créer un « pôle public bancaire et de l'assurance », transformer la BPI en banque publique de l'investissement, « socialiser certaines banques de détail » pour financer les très petites entreprises selon des critères sociaux et écologiques, et séparer strictement banques d'affaires et banques de détail. C'est une transformation profonde de la finance, avec aussi le contrôle des mouvements de capitaux. On peut en débattre. Mais le programme ne propose ni de nationaliser toutes les banques, ni de supprimer la propriété privée.\n\nL'histoire de France montre que les banques publiques ne sont pas une invention communiste. Le 2 décembre 1945, le gouvernement provisoire dirigé par le général de Gaulle nationalise la Banque de France et les quatre grandes banques de dépôt, dont le Crédit lyonnais et la Société générale, pour orienter l'épargne vers la reconstruction. En 1982, la gauche nationalise 39 banques et les compagnies Paribas et Suez : l'État contrôle alors environ 90 % des dépôts. Puis de nouvelles majorités les privatisent, à partir de 1986.\n\nAujourd'hui encore, l'État possède des banques. Bpifrance appartient à moitié à l'État et à moitié à la Caisse des dépôts, qui contrôle aussi La Poste et donc La Banque Postale. Parler de « communisme » pour un pôle public bancaire, c'est ignorer que la France en a déjà un, sous des gouvernements de toutes couleurs. Le vrai débat est ailleurs : à qui doit servir le crédit, et qui décide de son usage ?",
 empathie="On peut s'inquiéter pour son épargne ou se méfier de l'État quand on parle de banques. Ces inquiétudes sont normales ; elles méritent une réponse fondée sur le texte réel du programme.",
 legitimes=["Le programme de LFI propose bien de faire passer certaines banques sous contrôle public, ce qui est une rupture importante.", "On peut débattre de la capacité de l'État à bien gérer une banque.", "Le programme ne précise pas quelles banques seraient concernées ni comment les actionnaires seraient indemnisés."],
 contre=[
  ("Nationaliser, c'est forcément du communisme.", "En 1945, c'est le gouvernement du général de Gaulle qui a nationalisé les grandes banques. Des banques publiques existent dans de nombreuses démocraties de marché, y compris en France aujourd'hui."),
  ("Ils vont prendre l'argent des épargnants.", "Le programme parle de socialiser certaines banques de détail et de rendre gratuit le socle bancaire essentiel ; il ne prévoit pas de confisquer les dépôts."),
 ],
 questions=["Savais-tu que le général de Gaulle avait nationalisé les grandes banques en 1945 ?", "La Banque Postale et Bpifrance sont publiques : est-ce que cela fait de la France un pays communiste ?"],
 limites=["Le programme est une source partisane : il dit ce que LFI propose, pas ce qui serait réellement appliqué.", "La page lue est celle du programme 2027 mise à jour en novembre 2026 ; le texte peut encore évoluer.", "La date d'effet du 1er janvier 1946 vient du site d'histoire de BNP Paribas.", "Le Sénat a examiné un projet listant 36 banques ; l'Insee donne 39 banques dans la loi finale de 1982."],
 publics={'convaincus': "Le programme de LFI ne parle pas de nationaliser toutes les banques, mais de « socialiser certaines banques de détail ». Et c'est le général de Gaulle qui a nationalisé les grandes banques en 1945. Tu peux être contre cette mesure, mais ce n'est pas du communisme, sinon de Gaulle aussi était communiste.",
  'indecis': "LFI propose un pôle public bancaire, avec certaines banques de détail, pour financer les petites entreprises : c'est une vraie rupture qu'on peut discuter. Mais la France a déjà eu des banques nationalisées, et l'État possède aujourd'hui Bpifrance et La Banque Postale. Ce n'est pas un saut dans l'inconnu."},
 a_actualiser='2027-04-30', raison="Version définitive du programme pour l'élection présidentielle de 2027.",
))

# 5 ── Transferts d'argent des immigrés vers leur pays d'origine ────────────
