FICHES.append(fiche(
 id='vaccin-hpv-college', affirmation="Le vaccin contre le papillomavirus au collège est dangereux.", volet='services', sous_theme='Accès aux soins',
 mots_cles=['vaccin hpv', 'vaccin papillomavirus', 'gardasil dangereux', 'vaccination college', 'vaccin hpv college', 'hpv effets secondaires', 'gardasil guillain barre', 'vaccin papillomavirus garcons', 'collegien mort vaccin', 'cancer du col'],
 verdict='contredit', fiabilite='etabli',
 resume="Contredit. Le vaccin a été suivi sur des millions de jeunes : en France, une étude sur plus de 2,2 millions de jeunes filles ne trouve pas de hausse globale des maladies auto-immunes. Il existe un léger sur-risque de syndrome de Guillain-Barré, de l'ordre de 1 à 2 cas pour 100 000 vaccinées. En face, les HPV causent 6 400 cancers par an en France, et en Suède la vaccination avant 17 ans réduit le risque de cancer du col de 88 %. Le décès d'un collégien en 2023 est dû à une chute après un malaise : les autorités ont écarté un lien avec le vaccin.",
 contexte="Depuis la rentrée 2023, la vaccination contre les papillomavirus est proposée gratuitement aux élèves de 5e, filles et garçons, au collège. Le décès d'un collégien après une vaccination a nourri des inquiétudes.",
 explication="Il faut comparer les risques connus du vaccin, mesurés sur de grandes populations, aux cancers qu'il évite, et regarder précisément ce qui s'est passé lors de la campagne au collège.",
 sources=[B_HPV_ANSM_2015, B_HPV_ANSM_DOSSIER, B_HPV_QPHARMA_2023, B_HPV_CADUCEE_2025, B_HPV_KI_2020, B_HPV_VIDAL_2026],
 faits=[
  fait("Une étude de l'ANSM et de l'Assurance maladie sur plus de 2,2 millions de jeunes filles de 13 à 16 ans, suivies de 2008 à 2012, ne montre « pas d'augmentation du risque global de survenue de maladies auto-immunes » après vaccination.", 'b_hpv_ansm_2015', '2008-2012', 'France', "Le vaccin a été évalué sur une population immense, en conditions réelles.", 'etabli', '2,2 millions'),
  fait("Fait défavorable : la même étude conclut à une augmentation probable du risque de syndrome de Guillain-Barré, de l'ordre de 1 à 2 cas supplémentaires pour 100 000 jeunes filles vaccinées.", 'b_hpv_ansm_2015', '2008-2012', 'France', "Le risque existe, il est connu et rare ; l'ANSM juge les bénéfices « bien plus importants que les risques ».", 'etabli', '1 à 2 pour 100 000'),
  fait("Chaque année en France, 6 400 nouveaux cas de cancers sont causés par les HPV.", 'b_hpv_ansm_dossier', 'annuel', 'France', "C'est ce risque, bien plus fréquent, que le vaccin permet d'éviter.", 'etabli', '6 400'),
  fait("En Suède, sur près de 1,7 million de femmes suivies, celles vaccinées avant 17 ans ont réduit leur risque de cancer du col de l'utérus de 88 %.", 'b_hpv_ki_2020', '11 ans de suivi', 'Suède', "Vacciner jeune, avant les premières expositions au virus, est le plus efficace : d'où le choix du collège.", 'etabli', '88 %'),
  fait("Selon un bilan de l'ANSM rapporté par la presse médicale, pendant les premières semaines de la campagne au collège en 2023, l'agence a relevé 7 cas d'événements indésirables et conclu à « aucun nouveau signal de sécurité ».", 'b_hpv_qpharma_2023', '2023', 'France', "La campagne scolaire n'a pas révélé de danger nouveau.", 'etabli', '7'),
  fait("Fait défavorable : selon Caducée.net, en octobre 2023, un collégien de Saint-Herblain est mort d'un traumatisme crânien après une chute consécutive à un malaise suivant sa vaccination ; l'ARS a écarté tout lien avec le vaccin, mais un médecin a été mis en examen en 2025 pour « homicide involontaire » pour la prise en charge du malaise.", 'b_hpv_caducee_2025', '2023-2025', 'France', "Le drame tient à la surveillance après l'injection, pas au produit : d'où la consigne de surveiller 15 minutes et d'allonger l'élève en cas de malaise.", 'etabli'),
  fait("Selon Santé publique France, 116 541 vaccinations ont été réalisées en collège en 2024-2025 ; la couverture d'au moins une dose passe de 38 % à 54 % chez les filles concernées, loin de l'objectif de 80 % en 2030.", 'b_hpv_vidal_2026', '2024-2025', 'France', "La vaccination au collège rattrape un retard français, avec de fortes inégalités entre régions.", 'etabli', '54 %'),
 ],
 court="Le vaccin a été suivi sur des millions de jeunes : pas de hausse globale des maladies auto-immunes, et un sur-risque rare de Guillain-Barré, de 1 à 2 cas pour 100 000. En face, les HPV causent 6 400 cancers par an en France. Le collégien mort en 2023 a fait une chute après un malaise, et les autorités ont écarté un lien avec le vaccin.",
 moyen="En France, l'ANSM et l'Assurance maladie ont suivi plus de 2,2 millions de jeunes filles : pas d'augmentation globale des maladies auto-immunes. Elles ont trouvé un léger sur-risque de syndrome de Guillain-Barré, de 1 à 2 cas pour 100 000 vaccinées : un risque réel mais rare, déjà connu.\n\nEn face, les HPV causent 6 400 cancers par an en France. En Suède, la vaccination avant 17 ans réduit le risque de cancer du col de 88 %. Le collégien mort en 2023 a chuté après un malaise : l'ARS a écarté un lien avec le vaccin, et l'enquête porte sur la surveillance après l'injection. D'où la consigne : surveiller 15 minutes et allonger l'élève en cas de malaise.",
 detaille="Le vaccin contre les papillomavirus est l'un des mieux surveillés. En France, l'ANSM et l'Assurance maladie ont comparé plus de 2,2 millions de jeunes filles, vaccinées ou non, entre 2008 et 2012. Résultat : « pas d'augmentation du risque global » de maladies auto-immunes. Elles ont toutefois trouvé un sur-risque probable de syndrome de Guillain-Barré, de l'ordre de 1 à 2 cas supplémentaires pour 100 000 vaccinées. C'est un risque réel, qu'il ne faut pas cacher, mais rare et déjà inscrit dans la notice. Pendant les premières semaines de la campagne au collège, en 2023, l'ANSM a relevé 7 événements indésirables et aucun nouveau signal.\n\nEn face, le bénéfice est massif. Les HPV causent 6 400 nouveaux cancers par an en France : col de l'utérus, mais aussi cancers de l'anus et de la gorge, chez les femmes comme chez les hommes. En Suède, sur près de 1,7 million de femmes, celles vaccinées avant 17 ans ont réduit leur risque de cancer du col de 88 %. C'est pour cela qu'on vaccine au collège : avant les premières expositions au virus, gratuitement, pour tous, quel que soit le milieu social.\n\nLe drame de Saint-Herblain, en octobre 2023, a ému tout le pays. Le collégien a fait un malaise, a été installé sur une chaise au lieu d'être allongé, est tombé et est mort d'un traumatisme crânien. L'ARS a écarté tout lien avec le vaccin ; c'est la prise en charge du malaise qui fait l'objet d'une enquête judiciaire. La leçon, c'est l'organisation : surveiller 15 minutes et allonger l'élève en cas de malaise. Aujourd'hui, 54 % des filles concernées ont reçu au moins une dose, loin de l'objectif de 80 % : le vrai danger, ce sont les cancers évitables.",
 empathie="Il est normal que des parents s'inquiètent quand on vaccine leur enfant à l'école, encore plus après le drame de 2023. Cette inquiétude mérite des réponses précises, pas du mépris.",
 legitimes=["Un léger sur-risque de syndrome de Guillain-Barré a été observé.", "Un collégien est mort en 2023 après un malaise suivant une vaccination, et l'enquête judiciaire porte sur sa prise en charge.", "Les malaises après injection sont fréquents chez les adolescents et demandent une surveillance."],
 contre=[
  ("Un enfant est mort à cause du vaccin.", "Il est mort d'un traumatisme crânien après une chute consécutive à un malaise. L'ARS a écarté tout lien avec le vaccin ; l'enquête porte sur la prise en charge du malaise."),
  ("Le vaccin donne des maladies auto-immunes.", "Sur plus de 2,2 millions de jeunes filles, l'ANSM et l'Assurance maladie ne trouvent pas de hausse globale. Le seul sur-risque probable est le syndrome de Guillain-Barré, de 1 à 2 cas pour 100 000."),
  ("On n'a pas assez de recul.", "Les études portent sur plus de dix ans : en Suède, près de 1,7 million de femmes ont été suivies pendant 11 ans, avec une baisse de 88 % du risque de cancer du col chez les vaccinées avant 17 ans."),
 ],
 questions=["Sais-tu combien de cancers les papillomavirus causent chaque année en France ?", "Entre 1 à 2 cas de Guillain-Barré pour 100 000 et 6 400 cancers par an, quel risque te paraît le plus important ?"],
 limites=["L'étude de l'ANSM date de 2015 et porte sur la période 2008-2012 ; elle concernait les jeunes filles, avant l'extension aux garçons.", "Le bilan de pharmacovigilance de la campagne 2023 n'a été lu qu'à travers le début d'un article de presse ; le détail des 7 cas n'a pas été lu.", "Le bilan 2024-2025 de Santé publique France a été lu à travers l'article de VIDAL (la page de Santé publique France n'a pas pu être ouverte).", "L'étude suédoise a été lue à travers le communiqué de l'Institut Karolinska.", "L'enquête judiciaire sur le décès de Saint-Herblain n'est pas close à la date de lecture des sources."],
 publics={'convaincus': "Le vaccin a été suivi sur plus de 2,2 millions de jeunes filles en France : pas de hausse des maladies auto-immunes, et 1 à 2 cas de Guillain-Barré pour 100 000, un risque rare et connu. Le collégien mort en 2023 est tombé après un malaise ; l'enquête porte sur sa prise en charge, pas sur le produit. Pendant ce temps, les HPV causent 6 400 cancers par an.",
  'indecis': "Ton inquiétude est normale. Le vaccin a un risque rare et connu, mais il évite des cancers fréquents : en Suède, 88 % de cancers du col en moins chez les filles vaccinées avant 17 ans. Au collège, il est gratuit, et les règles de surveillance après l'injection ont été rappelées."},
 a_actualiser='2027-01-31', raison="Bilan de la campagne 2025-2026 et suites de l'enquête judiciaire.",
))

