FICHES.append(fiche(
 id='covid-origine-laboratoire', affirmation="Le covid a été fabriqué en laboratoire.", volet='politique', sous_theme='Désinformation',
 mots_cles=['covid fabrique', 'covid laboratoire', 'fuite de laboratoire', 'virus de wuhan', 'covid arme biologique', 'origine du covid', 'laboratoire de wuhan', 'covid cree par l homme', 'lab leak', 'virus fabrique'],
 verdict='inverifiable', fiabilite='debat',
 resume="Non démontré, et l'origine reste inconnue. L'idée d'un virus conçu volontairement, comme une arme, est rejetée par la quasi-totalité des scientifiques et par les agences de renseignement américaines. Pour l'OMS, en juin 2025, le poids des preuves disponibles suggère un passage de l'animal à l'homme, mais une fuite accidentelle de laboratoire n'est pas exclue : la Chine n'a pas fourni les données nécessaires. Les agences américaines restent divisées. Dire « fabriqué » affirme plus que ce qu'on sait.",
 contexte="Depuis 2020, l'origine du SARS-CoV-2 oppose deux hypothèses : un passage naturel de l'animal à l'homme, autour du marché de Huanan à Wuhan, ou un accident dans un laboratoire de la même ville. Sur les réseaux, la seconde devient souvent « le virus a été fabriqué », voire « c'est une arme ».",
 explication="Il faut distinguer trois affirmations : un virus conçu volontairement (arme biologique), un virus naturel ou modifié échappé accidentellement d'un laboratoire, et une transmission naturelle depuis l'animal. Les sources ne disent pas la même chose sur chacune.",
 sources=[C_CO_SAGO_2025, C_CO_PASTEUR_2023, C_CO_SCIENCE_2022, C_CO_ODNI_2021, C_CO_CIA_2025, C_CO_ACADEMIE_2023],
 faits=[
  fait("En juin 2025, le groupe d'experts de l'OMS (SAGO, 27 experts indépendants) conclut que « le poids des preuves disponibles » suggère une transmission de l'animal à l'homme, tout en jugeant que de nombreuses informations manquent.", 'c_co_sago_2025', '2025', 'Monde', "L'hypothèse naturelle est la mieux étayée, sans être prouvée.", 'interpretation'),
  fait("La Chine n'a pas transmis à l'OMS des centaines de séquences génétiques des premiers malades, ni les données sur les animaux vendus à Wuhan et sur la biosécurité des laboratoires ; le directeur général de l'OMS déclare que « toutes les hypothèses doivent rester sur la table ».", 'c_co_sago_2025', '2025', 'Chine', "L'opacité chinoise empêche de trancher, dans un sens comme dans l'autre.", 'etabli'),
  fait("Selon deux études publiées dans Science en juillet 2022, l'épidémie est probablement partie du marché de Huanan, où étaient vendus des animaux sensibles au virus, avec au moins deux passages de l'animal à l'homme.", 'c_co_science_2022', '2019-2022', 'Wuhan', "Ce sont des arguments forts pour l'origine naturelle, que leurs auteurs présentent comme probables, non certains.", 'interpretation'),
  fait("Selon l'Institut Pasteur, une fabrication intentionnelle du virus est rejetée par la quasi-totalité de la communauté scientifique ; l'hypothèse zoonotique est jugée « la plus probable » et la fuite de laboratoire « ne peut être écartée ».", 'c_co_pasteur_2023', '2023', 'Monde', "« Fabriqué » au sens de conçu volontairement n'est pas soutenu par les spécialistes.", 'interpretation'),
  fait("D'après le résumé déclassifié de l'évaluation du renseignement américain demandée par le président Biden, les agences s'accordent largement pour dire que le virus n'a pas été développé comme arme biologique ; la plupart estiment, avec une confiance faible, qu'il n'a probablement pas été génétiquement modifié.", 'c_co_odni_2021', 'après 2020', 'États-Unis', "Même les services les plus soupçonneux envers la Chine écartent l'idée d'une arme.", 'interpretation'),
  fait("Fait défavorable : en janvier 2025, la CIA a jugé une origine en laboratoire « plus probable », avec une confiance faible ; le FBI et le Département de l'Énergie soutiennent aussi la thèse d'une fuite, tandis que quatre autres agences penchent pour une origine naturelle.", 'c_co_cia_2025', '2021-2025', 'États-Unis', "L'hypothèse d'un accident de laboratoire est sérieuse et défendue par des institutions ; il ne faut pas la traiter comme un délire.", 'debat'),
  fait("Fait défavorable : lors d'une séance de l'Académie nationale de médecine en 2023, les intervenants ont estimé que « la communauté scientifique reste donc partagée » et ont discuté l'hypothèse d'expériences de gain de fonction, tout en écartant « quelque chose d'intentionnel ».", 'c_co_academie_2023', '2023', 'France', "Des scientifiques reconnus jugent la piste du laboratoire crédible : le débat est légitime, l'idée d'une arme ne l'est pas.", 'debat'),
 ],
 court="On ne sait pas encore d'où vient le covid. Pour l'OMS, le passage de l'animal à l'homme est le plus probable, mais un accident de laboratoire n'est pas exclu. L'idée d'un virus fabriqué exprès, comme une arme, est en revanche rejetée par presque tous les spécialistes.",
 moyen="Pour le groupe d'experts de l'OMS, en juin 2025, le poids des preuves suggère un passage naturel de l'animal à l'homme, sans doute autour du marché de Huanan à Wuhan. Mais la Chine n'a pas fourni des données essentielles, et l'OMS garde toutes les hypothèses ouvertes, y compris la fuite de laboratoire. Aux États-Unis, la CIA, le FBI et le Département de l'Énergie penchent pour un accident, quatre autres agences pour une origine naturelle, souvent avec une confiance faible.\n\nCe qui est quasiment exclu, c'est un virus conçu volontairement : les services de renseignement américains écartent l'arme biologique, et la quasi-totalité des scientifiques rejette une fabrication intentionnelle. Dire « le covid a été fabriqué » affirme donc plus que ce qu'on sait. La bonne formule : origine inconnue, accident de laboratoire possible, arme non.",
 detaille="L'origine du covid reste une question ouverte. En juin 2025, le groupe d'experts de l'OMS chargé de la question a conclu que le poids des preuves disponibles suggère un passage du virus de l'animal à l'homme. Deux études publiées dans Science en 2022 situent le départ de l'épidémie au marché de Huanan, à Wuhan, où étaient vendus vivants des animaux sensibles au virus. Des virus de chauves-souris très proches ont été trouvés au Laos.\n\nMais rien n'est prouvé. La Chine n'a pas transmis les séquences des premiers malades, les données sur les animaux vendus ni les informations sur ses laboratoires. L'hypothèse d'un accident dans un laboratoire de Wuhan est donc défendue sérieusement : la CIA la juge plus probable avec une faible confiance, le FBI et le Département de l'Énergie la soutiennent aussi, et des membres de l'Académie de médecine estiment que la communauté scientifique reste partagée. D'autres agences américaines penchent pour une origine naturelle.\n\nIl faut donc être précis sur les mots. « Fabriqué » au sens d'un virus conçu volontairement, ou d'une arme biologique, n'est soutenu ni par les scientifiques ni par les services de renseignement. « Échappé d'un laboratoire » reste une hypothèse possible, ni prouvée ni exclue. Ce débat mérite mieux que des certitudes : il pose de vraies questions sur la transparence des États et sur la sécurité des recherches sur les virus dangereux.",
 empathie="Après des années de confinements, de morts et de communication parfois contradictoire, il est normal de vouloir savoir d'où vient ce virus et de se méfier des versions officielles. La réponse honnête, c'est qu'on ne sait pas encore tout.",
 legitimes=["Une fuite accidentelle de laboratoire n'est pas exclue par l'OMS.", "La Chine n'a pas fourni les données nécessaires pour trancher.", "Des agences de renseignement américaines jugent la piste du laboratoire plus probable.", "La sécurité des recherches sur les virus dangereux est une vraie question."],
 contre=[
  ("On nous a traités de complotistes, et maintenant la CIA dit que c'est le laboratoire.", "La piste de l'accident a parfois été balayée trop vite, c'est vrai. Mais la CIA parle d'une hypothèse « plus probable » avec une confiance faible, pas d'une preuve, et personne ne parle d'arme : le renseignement américain l'a écartée."),
  ("Le virus a été créé pour vendre des vaccins.", "Aucune source sérieuse ne soutient cette idée : les services de renseignement écartent l'arme biologique, et les scientifiques une fabrication intentionnelle. L'hypothèse débattue est celle d'un accident, pas d'un plan."),
 ],
 questions=["Quelle différence fais-tu entre un virus échappé par accident et un virus fabriqué exprès ?", "Si la Chine ne donne pas ses données, peut-on vraiment affirmer quoi que ce soit avec certitude ?"],
 limites=["L'origine n'est pas tranchée : cette fiche devra évoluer si de nouvelles données sont publiées.", "Le communiqué de l'OMS a été lu dans sa version portugaise ; le rapport complet du SAGO n'a pas été lu.", "Le rapport déclassifié du renseignement américain n'a pas pu être ouvert directement (lu via un média spécialisé).", "La position de l'Académie de médecine n'a été lue qu'à travers des comptes rendus partiels ; son rapport d'avril 2025 n'a pas été consulté en entier.", "Les études publiées dans Science ont été lues à travers un communiqué de recherche."],
 publics={'convaincus': "La piste du laboratoire n'est pas absurde : l'OMS ne l'exclut pas, et la CIA la juge même plus probable, avec prudence. Mais aucune de ces sources ne dit que le virus a été fabriqué exprès : le renseignement américain écarte l'arme biologique. Méfie-toi de ceux qui transforment un doute légitime en certitude sur un complot.",
  'indecis': "Personne ne sait encore avec certitude d'où vient le covid : le passage naturel de l'animal est jugé le plus probable par l'OMS, mais un accident de laboratoire reste possible, notamment parce que la Chine n'a pas tout partagé. Ce qui est quasiment exclu, c'est un virus créé volontairement. Le vrai sujet, c'est la transparence et la sécurité des laboratoires."},
 a_actualiser='2027-06-30', raison="Nouvelles publications scientifiques, éventuelles données chinoises et nouvelles évaluations des services de renseignement.",
))

# 5 ── La loi Gayssot et la liberté de débattre de l'histoire ─────────────────
C_GA_AFP_2016 = ('c_ga_afp_2016', src("France : le délit de négationnisme constitutionnel", 'JusticeInfo.net (dépêche AFP)', '11 janvier 2016',
  'https://www.justiceinfo.net/fr?p=25381',
  "Saisi le 8 octobre 2015 par la Cour de cassation d'une question prioritaire de constitutionnalité sur l'article 24 bis de la loi du 29 juillet 1881, le Conseil constitutionnel le déclare conforme. Contester des crimes contre l'humanité sanctionnés par une juridiction française ou internationale constitue en soi une incitation au racisme et à l'antisémitisme ; la restriction est nécessaire, adaptée et proportionnée. « seule la négation, implicite ou explicite, ou la minoration outrancière de ces crimes est prohibée » ; « les dispositions contestées n'ont ni pour objet ni pour effet d'interdire les débats historiques ».",
  "Dépêche d'agence de presse sur la décision n° 2015-512 QPC du 8 janvier 2016.", 'secondaire'))
C_GA_DALLOZ_2016 = ('c_ga_dalloz_2016', src("Délit de révisionnisme jugé conforme à la Constitution", 'Dalloz Actualité (Sabrina Lavric)', '1er février 2016',
  'https://www.dalloz-actualite.fr/flash/delit-de-revisionnisme-juge-conforme-constitution',
  "Cons. const., 8 janv. 2016, n° 2015-512 QPC : l'article 24 bis de la loi du 29 juillet 1881, créé par la loi « Gayssot » du 13 juillet 1990 et modifié en 1992 et 2014, est conforme. Il punit « d'un an d'emprisonnement et de 45 000 € d'amende » ceux qui « auront contesté, par un des moyens énoncés à l'article 23, l'existence d'un ou plusieurs crimes contre l'humanité ».",
  "Revue juridique ; extrait en accès libre.", 'secondaire'))
C_GA_CEDH = ('c_ga_cedh', src("Fiche thématique : Discours de haine", 'Cour européenne des droits de l\'homme', 'novembre 2023',
  'https://prd-echr.coe.int/documents/d/echr/fs_hate_speech_fra',
  "Garaudy c. France (24 juin 2003) : requête irrecevable ; la contestation de crimes contre l'humanité est « l'une des formes les plus aigües de diffamation raciale » envers les Juifs, et l'article 17 empêche d'invoquer la liberté d'expression. M'Bala M'Bala c. France (20 octobre 2015) : un spectacle de 2008 honorant un négationniste relevait d'une « démonstration de haine et d'antisémitisme » ; requête irrecevable. Perinçek c. Suisse (Grande Chambre, 15 octobre 2015) : la condamnation d'un homme politique ayant nié la qualification de génocide pour les massacres d'Arméniens de 1915 viole la liberté d'expression.",
  "Juridiction européenne ; fiche de synthèse de sa jurisprudence.", 'primaire'))
C_GA_APPEL_2005 = ('c_ga_appel_2005', src("Liberté pour l'Histoire ! 19 historiens dénoncent… (texte de l'appel publié dans Libération)", 'Hérodote.net', 'page consultée le 12 novembre 2026',
  'https://www.herodote.net/Liberte_pour_l_Histoire_19_historiens_denoncent-article-60.php',
  "Appel publié dans Libération le 13 décembre 2005, signé par 19 historiens et intellectuels, dont Jean-Pierre Azéma, Marc Ferro, Pierre Nora, Mona Ozouf, René Rémond, Pierre Vidal-Naquet et Michel Winock. « L'histoire n'est pas une religion. » Les signataires demandent « l'abrogation de ces dispositions législatives indignes d'un régime démocratique », visant la loi du 13 juillet 1990, les lois du 29 janvier et du 21 mai 2001 et la loi du 23 février 2005.",
  "Site de vulgarisation historique reproduisant le texte de l'appel.", 'secondaire'))
C_GA_AN_2008 = ('c_ga_an_2008', src("Rapport d'activité 2008 de l'Assemblée nationale : mission d'information sur les questions mémorielles", 'Assemblée nationale', '2008',
  'https://www.assemblee-nationale.fr/connaissance/rapactiv2008/rapactiv2008-40-41.pdf',
  "La mission d'information sur les questions mémorielles, présidée par Bernard Accoyer, a « entendu soixante-neuf personnalités » et formulé dix-huit recommandations. « le rôle du Parlement n'est pas d'adopter des lois portant une appréciation sur des faits historiques » ; le vote de résolutions (« le nouvel article 34-1 de la Constitution ») est un meilleur outil. Le Parlement est en revanche dans son rôle pour « lutter contre le racisme et la xénophobie ».",
  "Document officiel de l'Assemblée nationale.", 'primaire'))
C_GA_CC_2012 = ('c_ga_cc_2012', src("Décision n° 2012-647 DC du 28 février 2012 (loi visant à réprimer la contestation de l'existence des génocides reconnus par la loi)", 'Conseil constitutionnel (texte reproduit par la Revue générale du droit)', '28 février 2012',
  'https://www.revuegeneraledudroit.eu/blog/decisions/cc-n2012-647-dc-loi-visant-a-reprimer-la-contestation-de-lexistence-des-genocides-reconnus-par-la-loi',
  "Une loi qui « reconnaît » un génocide n'a pas en elle-même de portée normative ; en réprimant la contestation de crimes « reconnus comme tels par la loi française », le législateur « a porté une atteinte inconstitutionnelle à l'exercice de la liberté d'expression et de communication ». La loi est déclarée contraire à la Constitution.",
  "Décision de la juridiction constitutionnelle.", 'primaire'))

FICHES.append(fiche(
 id='loi-gayssot-liberte', affirmation="La loi Gayssot empêche de débattre librement de l'histoire.", volet='droits', sous_theme='Libertés publiques',
 mots_cles=['loi gayssot', 'gayssot', 'negationnisme', 'liberte d expression histoire', 'lois memorielles', 'on ne peut plus debattre de l histoire', 'revisionnisme interdit', 'article 24 bis', 'delit de negationnisme', 'verite officielle'],
 verdict='trompeur', fiabilite='interpretation',
 resume="Trompeur. La loi Gayssot de 1990 ne punit pas le débat historique : elle punit la négation, ou la minoration outrancière, de crimes contre l'humanité déjà jugés, en pratique la Shoah. Le Conseil constitutionnel l'a validée en 2016 en précisant qu'elle n'a « ni pour objet ni pour effet d'interdire les débats historiques », et la Cour européenne des droits de l'homme juge que le négationnisme n'est pas protégé. Mais la critique existe : en 2005, 19 historiens réputés demandaient l'abrogation des lois mémorielles, dont celle-ci.",
 contexte="Les négationnistes et une partie de l'extrême droite présentent la loi Gayssot comme une « vérité officielle » imposée, qui interdirait toute recherche ou tout débat sur la Seconde Guerre mondiale.",
 explication="Il faut lire ce que la loi réprime exactement, ce qu'en ont dit les juges français et européens, et ce que lui reprochent des historiens qui n'ont rien de négationnistes.",
 sources=[C_GA_AFP_2016, C_GA_DALLOZ_2016, C_GA_CEDH, C_GA_APPEL_2005, C_GA_AN_2008, C_GA_CC_2012],
 faits=[
  fait("Selon Dalloz Actualité, l'article 24 bis de la loi de 1881, créé par la loi Gayssot du 13 juillet 1990, punit d'un an d'emprisonnement et de 45 000 € d'amende ceux qui contestent l'existence d'un ou plusieurs crimes contre l'humanité.", 'c_ga_dalloz_2016', '1990-2016', 'France', "Le délit vise des crimes établis par la justice, pas l'interprétation de l'histoire en général.", 'etabli', '45 000 €'),
  fait("Le 8 janvier 2016, le Conseil constitutionnel a jugé la loi conforme : seule « la négation, implicite ou explicite, ou la minoration outrancière » de ces crimes est interdite, et elle n'a « ni pour objet ni pour effet d'interdire les débats historiques ».", 'c_ga_afp_2016', '2016', 'France', "Les historiens restent libres d'étudier, de discuter et de réviser les connaissances sur la période.", 'etabli'),
  fait("La Cour européenne des droits de l'homme a jugé en 2003 (Garaudy c. France) que la contestation de crimes contre l'humanité est « l'une des formes les plus aigües de diffamation raciale » et ne relève pas de la liberté d'expression ; elle a confirmé cette ligne en 2015 pour un spectacle honorant un négationniste.", 'c_ga_cedh', '2003-2015', 'Europe', "Pour la Cour, le négationnisme est un abus de la liberté d'expression, pas un débat d'idées.", 'etabli'),
  fait("En 2012, le Conseil constitutionnel a censuré une loi qui punissait la contestation des génocides « reconnus par la loi », jugeant qu'elle portait une atteinte inconstitutionnelle à la liberté d'expression.", 'c_ga_cc_2012', '2012', 'France', "Le juge ne valide pas n'importe quelle loi mémorielle : il exige que les crimes aient été jugés par un tribunal, pas seulement qualifiés par le Parlement.", 'etabli'),
  fait("Fait défavorable : le 13 décembre 2005, 19 historiens, dont Pierre Nora, Mona Ozouf et Pierre Vidal-Naquet, ont signé l'appel « Liberté pour l'histoire », jugeant que « L'histoire n'est pas une religion » et demandant l'abrogation des lois mémorielles, loi Gayssot comprise.", 'c_ga_appel_2005', '2005', 'France', "Des historiens éminents, nullement négationnistes, contestent le principe d'une loi pénale sur l'histoire : le débat sur l'outil est légitime.", 'interpretation'),
  fait("Fait défavorable : en 2008, la mission de l'Assemblée nationale présidée par Bernard Accoyer a estimé que « le rôle du Parlement n'est pas d'adopter des lois portant une appréciation sur des faits historiques », tout en rappelant son rôle pour lutter contre le racisme.", 'c_ga_an_2008', '2008', 'France', "Le Parlement lui-même a choisi de ne plus voter de nouvelles lois mémorielles, sans abroger la loi Gayssot.", 'etabli'),
  fait("Fait défavorable : la Cour européenne a jugé en 2015 (Perinçek c. Suisse) que condamner un homme politique pour avoir nié la qualification de génocide pour les massacres d'Arméniens violait la liberté d'expression.", 'c_ga_cedh', '2015', 'Europe', "La frontière entre négationnisme et débat est discutée en droit ; elle dépend du contexte et des crimes concernés.", 'etabli'),
 ],
 court="La loi Gayssot ne punit pas le débat historique : elle punit la négation de crimes contre l'humanité déjà jugés, comme la Shoah. Le Conseil constitutionnel a précisé en 2016 qu'elle n'interdit pas les débats historiques. Des historiens critiquent pourtant le principe des lois mémorielles.",
 moyen="La loi Gayssot de 1990 punit d'un an de prison et de 45 000 € d'amende ceux qui contestent l'existence de crimes contre l'humanité jugés par un tribunal, en pratique la Shoah. En 2016, le Conseil constitutionnel l'a jugée conforme : seule la négation ou la « minoration outrancière » est interdite, pas les débats historiques. La Cour européenne des droits de l'homme considère aussi le négationnisme comme une forme de haine raciale.\n\nLe débat sur l'outil existe pourtant. En 2005, 19 historiens de renom, dont Pierre Nora et Pierre Vidal-Naquet, demandaient l'abrogation des lois mémorielles : « L'histoire n'est pas une religion. » En 2008, une mission parlementaire a jugé que le Parlement ne devait plus voter de lois sur l'histoire. Mais ces critiques ne défendent pas les négationnistes : ils contestent la méthode, pas les faits.",
 detaille="Que dit la loi ? Depuis 1990, l'article 24 bis de la loi sur la presse punit d'un an de prison et de 45 000 € d'amende la contestation de crimes contre l'humanité jugés par une juridiction française ou internationale. Elle vise en pratique la négation de la Shoah. Elle n'interdit ni la recherche, ni les controverses sur les chiffres, les responsabilités ou les interprétations, qui continuent dans les universités.\n\nLes juges l'ont confirmé. En 2016, le Conseil constitutionnel a jugé que seule « la négation, implicite ou explicite, ou la minoration outrancière » de ces crimes est interdite, et que la loi n'a « ni pour objet ni pour effet d'interdire les débats historiques ». La Cour européenne des droits de l'homme estime depuis 2003 que nier ces crimes est une forme de diffamation raciale envers les Juifs. Et quand le Parlement a voulu punir la négation d'autres génocides simplement « reconnus par la loi », le Conseil constitutionnel l'a censuré en 2012 au nom de la liberté d'expression.\n\nLa critique n'est pas réservée aux négationnistes. En 2005, 19 historiens de premier plan ont demandé l'abrogation des lois mémorielles, loi Gayssot comprise, car « L'histoire n'est pas une religion ». En 2008, l'Assemblée nationale a estimé que ce n'est pas son rôle de juger l'histoire. On peut donc discuter de l'outil pénal. Mais ceux qui disent « on ne peut plus débattre » cherchent souvent à faire passer la négation d'un crime prouvé pour une opinion comme une autre.",
 empathie="On peut tenir à la liberté d'expression et se méfier de tout ce qui ressemble à une vérité imposée par l'État. Cette vigilance est saine : elle mérite de savoir précisément ce que la loi interdit.",
 legitimes=["Des historiens reconnus, de sensibilités diverses, critiquent le principe des lois mémorielles.", "Le Parlement a lui-même renoncé à voter de nouvelles lois sur l'histoire.", "La Cour européenne a protégé, dans un autre contexte, la contestation de la qualification d'un génocide."],
 contre=[
  ("C'est une vérité officielle, on n'a pas le droit de chercher.", "La recherche sur la Seconde Guerre mondiale est libre et très active. Ce qui est puni, c'est de nier des crimes établis par la justice, pas de discuter des sources ou des interprétations."),
  ("Si leurs arguments étaient faux, pas besoin de loi.", "C'est l'argument des historiens qui critiquent la loi, et il se discute. Mais le Conseil constitutionnel et la Cour européenne considèrent la négation de la Shoah comme une incitation à la haine des Juifs, pas comme une thèse scientifique."),
 ],
 questions=["Peux-tu citer un débat historique sérieux qui aurait été interdit par cette loi ?", "Pourquoi, selon toi, la négation de la Shoah intéresse-t-elle surtout des militants antisémites et pas les historiens ?"],
 limites=["La décision du Conseil constitutionnel de 2016 a été lue à travers une dépêche AFP et un article juridique, la page officielle n'ayant pas pu être ouverte.", "Le rapport Accoyer n'a été lu qu'à travers sa présentation dans le rapport d'activité de l'Assemblée nationale.", "Le nombre de condamnations prononcées au titre de cet article n'a pas été vérifié."],
 publics={'convaincus': "Tu peux lire tous les livres d'histoire que tu veux et discuter de tout : chiffres, responsabilités, interprétations. La loi punit seulement le fait de nier des crimes jugés, comme la Shoah, et le Conseil constitutionnel a écrit qu'elle n'interdit pas les débats historiques. Ceux qui se disent censurés sont presque toujours des négationnistes qui veulent faire passer une haine pour une opinion.",
  'indecis': "Se méfier d'une loi qui touche à l'histoire, c'est légitime, et de grands historiens l'ont fait. Mais la loi Gayssot ne vise que la négation de crimes contre l'humanité déjà jugés, pas la recherche. On peut débattre de l'outil pénal sans croire qu'on « ne peut plus rien dire » sur l'histoire."},
 a_actualiser='2028-06-30', raison="Nouvelles décisions de justice ou propositions de loi sur les lois mémorielles.",
))

