 faits=[
  fait("À PISA 2025, les élèves français de 15 ans obtiennent 456 points en compréhension de l'écrit, en baisse de 18 points depuis 2022 ; 33 % sont sous le niveau 2, contre 15 % en 2000.", 'd_el_depp_pisa_2026', '2000-2025', 'France', "La baisse du niveau est réelle et forte.", 'etabli', '33 %'),
  fait("La France reste dans la moyenne de l'OCDE (461 points), qui recule aussi de 14 points depuis 2022 ; les élèves français déclarent 3 heures d'écran de loisirs par jour d'école, contre 3,4 heures en moyenne dans l'OCDE.", 'd_el_depp_pisa_2026', '2025', 'France et OCDE', "Les jeunes Français ne sont pas plus exposés aux écrans que les autres, et la baisse est générale.", 'etabli', '3 h'),
  fait("Les 7-19 ans lisent en moyenne 19 minutes par jour et passent 3 h 11 sur les écrans ; chez les garçons de 16-19 ans, la lecture-loisir a perdu 15 points depuis 2022.", 'd_el_culture_2024', '2024', 'France', "Le goût de lire recule nettement, surtout chez les adolescents.", 'estimation', '19 minutes'),
  fait("La commission d'experts sur les écrans juge les effets observés « de faible amplitude » et sans causalité démontrée ; plus de deux heures d'écran par jour « pourrait être associé » à de moins bons résultats en lecture, « mais cela reste à confirmer ». Pour les adolescents, le milieu social est selon elle « la variable la plus explicative des différences observées dans le domaine cognitif ».", 'd_el_commission_2024', '2024', 'France', "Les écrans ne sont pas innocents, mais la science ne permet pas d'en faire la cause unique.", 'etabli'),
  fait("À PISA 2025, l'écart entre élèves très favorisés et très défavorisés atteint 91 points en France, contre 77 dans l'OCDE.", 'd_el_depp_pisa_2026', '2025', 'France', "Les inégalités sociales pèsent davantage que les écrans.", 'etabli', '91 points'),
  fait("En CM1, la baisse a commencé avant les smartphones : 525 points à PIRLS en 2001, puis 514 en 2021, un niveau stable depuis 2016 alors que la plupart des pays européens reculaient.", 'd_el_pirls_2023', '2001-2021', 'France', "Le déclin est ancien et a d'autres causes que les réseaux sociaux.", 'etabli', '514'),
  fait("Fait défavorable : selon Euronews, le ministère cite l'usage croissant des écrans et des réseaux sociaux parmi les causes de la baisse à PISA 2025, et l'OCDE alerte sur la consommation rapide de contenus, qui nuit à la lecture de textes complexes.", 'd_el_euronews_2026', '2026', 'France et OCDE', "Les écrans font partie du problème, à côté d'autres facteurs comme le manque d'enseignants.", 'interpretation'),
 ],
 court="Le niveau de lecture baisse vraiment, et les jeunes lisent moins pour le plaisir. Mais les experts ne trouvent que des liens faibles avec les écrans, sans causalité prouvée. Le milieu social et les moyens de l'école pèsent bien plus lourd.",
 moyen="La baisse est réelle : à PISA 2025, 33 % des élèves français de 15 ans sont sous le niveau de base en lecture, contre 15 % en 2000. Les 7-19 ans lisent 19 minutes par jour pour 3 h 11 d'écrans. Il y a donc un vrai problème.\n\nMais accuser seulement les écrans ne tient pas. La commission d'experts de 2024 juge les effets « de faible amplitude » et non démontrés comme causes. Les jeunes Français passent moins de temps sur les écrans de loisir que la moyenne de l'OCDE. Et le facteur qui pèse le plus reste le milieu social : 91 points d'écart entre élèves favorisés et défavorisés en France, plus que dans l'OCDE.",
 detaille="Il ne faut pas nier le problème. À PISA 2025, les élèves français de 15 ans obtiennent 456 points en compréhension de l'écrit, 18 de moins qu'en 2022, et 33 % sont sous le niveau de base, contre 15 % en 2000. Le goût de lire recule aussi : les 7-19 ans lisent 19 minutes par jour, et les garçons de 16-19 ans sont de moins en moins nombreux à lire pour leurs loisirs. Pendant ce temps, ils passent 3 h 11 par jour sur les écrans.\n\nMais dire que les écrans en sont la cause, c'est aller plus loin que la science. La commission d'experts réunie en 2024 conclut que les études montrent des associations « de faible amplitude », sans causalité démontrée : au-delà de deux heures par jour, un lien avec de moins bons résultats en lecture est possible, « mais cela reste à confirmer ». Les jeunes Français passent d'ailleurs moins de temps sur les écrans de loisir que la moyenne de l'OCDE. Et la baisse a commencé bien avant les smartphones : en CM1, la France est passée de 525 points en 2001 à 514 en 2021.\n\nLe facteur qui pèse le plus est ailleurs. Pour les experts, le milieu social est la variable la plus explicative des écarts chez les adolescents ; en France, l'écart entre élèves favorisés et défavorisés atteint 91 points, plus que dans l'OCDE. L'OCDE relève aussi la pénurie d'enseignants. Pour la gauche, protéger les enfants des écrans est utile, mais la vraie réponse passe par des classes moins chargées, des enseignants mieux formés et payés, des bibliothèques et une lutte résolue contre les inégalités.",
 empathie="Beaucoup de parents et de grands-parents voient les enfants scotchés à leur téléphone et s'inquiètent de ne plus les voir lire. Cette inquiétude est fondée sur quelque chose de réel.",
 legitimes=["Le niveau en lecture baisse réellement, et fortement depuis 2018.", "Les jeunes lisent moins pour le plaisir et passent beaucoup de temps sur les écrans.", "Un usage excessif des écrans, surtout le soir, nuit au sommeil, donc aux apprentissages."],
