FICHES.append(fiche(
 id='trump-homme-de-paix', affirmation="Trump est un homme de paix qui a arrêté des guerres.", volet='international', sous_theme='États-Unis',
 mots_cles=['trump homme de paix', 'trump a arrete des guerres', 'trump huit guerres', 'trump sept guerres', 'trump prix nobel', 'trump paix gaza', 'trump pacifiste', 'trump guerre iran', 'trump venezuela', 'trump ukraine paix'],
 verdict='trompeur', fiabilite='etabli',
 resume="Trompeur. Donald Trump a réellement contribué à certains accords : le cessez-le-feu à Gaza d'octobre 2025, une déclaration de paix entre l'Arménie et l'Azerbaïdjan, un cessez-le-feu entre Israël et l'Iran en juin 2025. Mais les vérificateurs (PolitiFact, AP) jugent son bilan de « sept » ou « huit guerres » arrêtées exagéré : plusieurs n'étaient pas des guerres, d'autres continuent. Et il a lui-même bombardé l'Iran en 2025, lancé une guerre contre l'Iran avec Israël en février 2026, capturé le président vénézuélien et fait tuer au moins 227 personnes en mer selon Human Rights Watch.",
 contexte="Donald Trump se présente comme le président qui « arrête les guerres » et revendique le prix Nobel de la paix. Ses soutiens, en France aussi, reprennent ce récit.",
 explication="Il faut vérifier, conflit par conflit, ce qui a été réellement arrêté, et mettre en face les guerres et les opérations militaires que son administration a lancées.",
 sources=[E_TP_POLITIFACT_2025, E_TP_AP_2025, E_TP_AFP_GAZA_2025, E_TP_ONU_IRAN_2025, E_TP_AFP_IRAN_2026, E_TP_HRW_2026, E_TP_AFP_VEN_2026, E_TP_ALJAZEERA_2026, E_TP_AFP_UKR_2026],
 faits=[
  fait("PolitiFact a jugé « Mostly False » (plutôt faux) l'affirmation de Trump selon laquelle il a mis fin à sept guerres : le différend Égypte-Éthiopie n'est pas une guerre, rien n'indiquait une guerre imminente entre la Serbie et le Kosovo, et les combats ont continué en RDC et entre le Cambodge et la Thaïlande.", 'e_tp_politifact_2025', '2025', 'Monde', "Le compte de Trump mélange vrais cessez-le-feu, accords fragiles et conflits qui n'existaient pas.", 'etabli'),
  fait("L'agence AP juge que le décompte de « huit guerres » est faux : au Congo, « the conflict is far from over », le traité Arménie-Azerbaïdjan n'est ni signé ni ratifié, et à Gaza « far more work remains ».", 'e_tp_ap_2025', '2025', 'Monde', "Certaines médiations ont aidé, mais la paix n'est pas acquise.", 'etabli'),
  fait("Fait défavorable : le cessez-le-feu à Gaza, négocié sous l'égide des États-Unis, est entré en vigueur le 10 octobre 2025 ; le Hamas a libéré les 20 otages vivants et Israël près de 2 000 prisonniers palestiniens.", 'e_tp_afp_gaza_2025', '2025', 'Gaza', "C'est un résultat réel de la diplomatie américaine, même si des Palestiniens continuent d'être tués.", 'etabli', '20'),
  fait("Fait défavorable : selon PolitiFact, Trump a joué un rôle dans le cessez-le-feu entre Israël et l'Iran du 24 juin 2025 et dans la déclaration de paix entre l'Arménie et l'Azerbaïdjan signée à la Maison-Blanche le 8 août 2025.", 'e_tp_politifact_2025', '2025', 'Moyen-Orient / Caucase', "Ces avancées existent ; elles ne font pas de lui un « homme de paix » au vu du reste de son bilan.", 'etabli'),
  fait("Le 21 juin 2025, les États-Unis ont bombardé trois sites nucléaires iraniens ; le secrétaire général de l'ONU a dénoncé une « escalade dangereuse » et rappelé qu'il n'y a « pas de solution militaire ».", 'e_tp_onu_iran_2025', '2025', 'Iran', "Le cessez-le-feu de juin 2025 est venu après des frappes américaines.", 'etabli'),
  fait("Le 28 février 2026, les États-Unis et Israël ont lancé une guerre contre l'Iran ; au 4 mars, une agence gouvernementale iranienne comptait au moins 1 045 morts en Iran, et six soldats américains avaient été tués.", 'e_tp_afp_iran_2026', '2026', 'Iran / Moyen-Orient', "Trump a déclenché une guerre majeure dans une région déjà en feu.", 'etabli', '1 045'),
  fait("Selon Human Rights Watch, depuis le 2 septembre 2025, les frappes américaines contre des embarcations dans les Caraïbes et le Pacifique ont fait au moins 227 morts en 69 frappes, qualifiées d'« exécutions extrajudiciaires ».", 'e_tp_hrw_2026', '2025-2026', 'Amérique latine', "L'usage de la force hors de tout cadre légal est l'inverse d'une politique de paix.", 'etabli', '227'),
  fait("Selon Al Jazeera, Trump a demandé environ 1 500 milliards de dollars pour l'armée pour l'exercice 2027, une hausse de près de 40 %, tout en réduisant des programmes sociaux et climatiques.", 'e_tp_aljazeera_2026', '2026-2027', 'États-Unis', "Un budget militaire record financé par des coupes sociales.", 'etabli'),
 ],
 court="Trump a aidé à obtenir quelques accords, comme le cessez-le-feu à Gaza en octobre 2025. Mais les vérificateurs jugent son bilan de « huit guerres arrêtées » exagéré. Et il a bombardé l'Iran, lancé une guerre contre ce pays en 2026, capturé le président vénézuélien et fait tuer au moins 227 personnes en mer selon Human Rights Watch.",
 moyen="Il faut reconnaître ce qui est réel : le cessez-le-feu à Gaza, entré en vigueur le 10 octobre 2025, a permis la libération des otages vivants, et Trump a aidé à un cessez-le-feu entre Israël et l'Iran et à une déclaration de paix entre l'Arménie et l'Azerbaïdjan. Mais PolitiFact juge son bilan de « sept guerres » arrêtées « plutôt faux » : certains conflits n'étaient pas des guerres, d'autres continuent.\n\nSurtout, Trump fait aussi la guerre. Il a bombardé des sites nucléaires iraniens en juin 2025, puis lancé avec Israël une guerre contre l'Iran le 28 février 2026. Ses frappes contre des bateaux ont fait au moins 227 morts selon Human Rights Watch, et l'armée américaine a capturé le président vénézuélien. Il demande un budget militaire record de 1 500 milliards de dollars.",
 detaille="Donald Trump dit avoir arrêté sept, puis huit guerres. Les vérificateurs ont regardé conflit par conflit. PolitiFact conclut que l'affirmation est « plutôt fausse » : le différend entre l'Égypte et l'Éthiopie n'est pas une guerre, rien n'indiquait une guerre imminente entre la Serbie et le Kosovo, et les combats ont continué en République démocratique du Congo comme entre le Cambodge et la Thaïlande. L'agence AP note qu'au Congo « the conflict is far from over ».\n\nIl y a pourtant des résultats. Le cessez-le-feu à Gaza, négocié sous l'égide des États-Unis, est entré en vigueur le 10 octobre 2025 et a permis la libération des 20 otages vivants. Trump a aussi contribué au cessez-le-feu entre Israël et l'Iran de juin 2025 et à une déclaration de paix entre l'Arménie et l'Azerbaïdjan. En Ukraine, en revanche, la guerre continue : en octobre 2026, la Russie exigeait toujours le retrait ukrainien du Donetsk.\n\nMais un homme de paix ne bombarde pas. En juin 2025, les États-Unis ont frappé trois sites nucléaires iraniens. Le 28 février 2026, ils ont lancé avec Israël une guerre contre l'Iran, qui a fait au moins 1 045 morts en Iran en quelques jours selon les autorités iraniennes. Depuis septembre 2025, leurs frappes contre des embarcations ont tué au moins 227 personnes, des « exécutions extrajudiciaires » selon Human Rights Watch. En janvier 2026, l'armée américaine a frappé Caracas et capturé le président vénézuélien. Et Trump demande 1 500 milliards de dollars pour l'armée en coupant dans les programmes sociaux. La paix par la force, c'est d'abord la force.",
 empathie="On peut être las des guerres sans fin et voir d'un bon œil un dirigeant qui promet d'y mettre fin. Cette envie de paix est juste ; elle mérite qu'on regarde tout son bilan.",
 legitimes=["Trump a contribué au cessez-le-feu à Gaza d'octobre 2025.", "Il a aidé à des cessez-le-feu ou déclarations de paix (Israël-Iran en juin 2025, Arménie-Azerbaïdjan).", "D'autres présidents américains ont aussi mené des guerres."],
 contre=[
  ("Il a ramené les otages de Gaza.", "C'est vrai, et c'est important. Mais le même président a lancé une guerre contre l'Iran quelques mois plus tard et fait tuer des centaines de personnes en mer sans jugement."),
  ("Les autres présidents ont fait pire.", "Comparer ne change rien aux faits : bombarder l'Iran, capturer un chef d'État étranger et frapper des bateaux sans procès, ce n'est pas une politique de paix."),
  ("Il a arrêté huit guerres.", "Les vérificateurs de PolitiFact et d'AP montrent que plusieurs n'étaient pas des guerres et que d'autres continuent."),
 ],
 questions=["Sais-tu quelles sont les « huit guerres » que Trump dit avoir arrêtées ?", "Peut-on être un homme de paix et lancer une guerre contre l'Iran ?"],
 limites=["L'article d'AP n'affiche pas de date ; il est postérieur au 27 décembre 2025.", "Les bilans de la guerre de 2026 contre l'Iran sont partiels (au 4 mars 2026) et viennent des autorités iraniennes.", "La demande budgétaire américaine n'est pas encore votée et a été lue via Al Jazeera.", "Les accords d'Abraham de 2020 n'ont pas été vérifiés dans une source lue."],
 publics={'convaincus': "Trump a obtenu le cessez-le-feu à Gaza, c'est vrai. Mais le même Trump a bombardé l'Iran, lancé une guerre contre lui en 2026, capturé le président vénézuélien et fait tuer au moins 227 personnes en mer selon Human Rights Watch. Un homme de paix, ce n'est pas celui qui choisit ses guerres.",
  'indecis': "Vouloir la paix, c'est sain, et certains accords de Trump ont compté. Mais les vérificateurs montrent que son compte de « guerres arrêtées » est gonflé, et il a lui-même lancé des opérations militaires lourdes. Le repère : regarder tout le bilan, pas seulement les annonces."},
 a_actualiser='2027-01-31', raison="Évolution de la guerre contre l'Iran, des négociations sur l'Ukraine et du cessez-le-feu à Gaza.",
))

